uniform float iTime;
uniform vec2 iResolution;
uniform vec4 iMouse;
uniform sampler2D iChannel0;

// Parameter mappings
uniform float u_speed;
uniform float u_scale;
uniform float u_intensity;
uniform float u_color_cycle;
uniform float u_layers;
uniform float u_density;
uniform float u_connection_radius;
uniform float u_pulse_intensity;
uniform float u_color_base;
uniform float u_color_pulse;
uniform float u_neon_glow;
uniform float u_bloom;

out vec4 fragColor;

// --- Helper Functions (Fluid Dynamics) ---

mat2 rot(float a) {
    float s = sin(a), c = cos(a);
    return mat2(c, -s, s, c);
}

// 2D Hash for smooth noise
float hash(vec2 p) {
    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}

// 2D Value Noise (Smooth, non-chaotic random waves)
float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    // Cubic interpolation for extra smooth curves
    f = f * f * (3.0 - 2.0 * f);
    return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), f.x),
               mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), f.x), f.y);
}

// Fractional Brownian Motion (Layers the noise for organic fluid look)
float fbm(vec2 p) {
    float v = 0.0;
    float a = 0.5;
    mat2 r = rot(0.37); // Slight rotation to break up grid patterns
    for (int i = 0; i < 4; i++) {
        v += a * noise(p);
        p = p * 2.0 * r;
        a *= 0.5;
    }
    return v;
}

vec3 hsv2rgb(vec3 c) {
    vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
    vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
    return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}

void main() {
    // Correct Aspect Ratio UVs
    vec2 uv = (gl_FragCoord.xy - 0.5 * iResolution.xy) / iResolution.y;
    vec2 uv0 = uv;
    vec2 mouseOffset = (iMouse.z > 0.0) ? (iMouse.xy / iResolution.xy - 0.5) : vec2(0.0);

    // --- Calming Pacing ---
    float spd = (u_speed <= 0.0) ? 0.2 : u_speed * 0.2; // Dialed down for fluid movement
    float t = iTime * spd;

    // Parameter re-mapping for Fluid mechanics
    float scaleBase = (u_scale <= 0.0) ? 1.0 : u_scale * 0.5;
    float layerCount = clamp(u_layers, 1.0, 8.0);

    // Density now controls how tightly packed the fluid ribbons are
    float ribbonDensity = (u_density <= 0.0) ? 1.0 : u_density * 8.0; 

    // Connection Radius now controls how heavily warped/wavy the fluid gets
    float turbulence = (u_connection_radius <= 0.0) ? 1.5 : u_connection_radius * 0.3;
    float pulseInt = u_pulse_intensity * 1.5;

    // --- Smooth Color Generation ---
    float hueBase = fract(u_color_base + (t * u_color_cycle * 0.02));
    float huePulse = fract(u_color_pulse + (t * u_color_cycle * 0.02));

    vec3 baseCol = hsv2rgb(vec3(hueBase, 0.75, 1.0));
    vec3 pulseCol = hsv2rgb(vec3(huePulse, 0.85, 1.0));

    // Deep Fluid Background
    vec3 finalColor = baseCol * 0.05 * length(uv0);

    // --- Infinite Layered Flow Field ---
    for(int i = 0; i < 8; i++) {
        float fi = float(i);
        if(fi >= layerCount) break;

        // Endless smooth zooming/drifting inward
        float z = fract(fi * 0.15 - t * 0.1); 
        float fade = smoothstep(0.0, 0.3, z) * smoothstep(1.0, 0.7, z);

        // Parallax depth scaling
        float size = mix(10.0, 1.0, z) * scaleBase;
        vec2 layerUV = (uv + mouseOffset * (1.0 - z) * 0.5) * size;

        // Gentle rotation per layer for depth complexity
        layerUV *= rot(fi * 0.8 + t * 0.05);

        // 1. Generate the underlying fluid terrain (Domain Warping)
        vec2 flowVector = vec2(t * 0.3, sin(t * 0.2) * 0.5);
        float fluidShape = fbm(layerUV + flowVector);

        // Add turbulence to create swirling eddies
        layerUV += fbm(layerUV * 2.0 - flowVector) * turbulence;

        // 2. Create the non-intersecting Topographic Lines (Isolines)
        // We use a sine wave mapped over the noise to create perfectly parallel, wavy ribbons
        float wavePhase = fluidShape * ribbonDensity - t * 2.0;
        float ribbonWave = sin(wavePhase);

        // Sharpen the waves into glowing threads
        float threadThickness = 0.92; // High value = thinner threads
        float ribbon = smoothstep(threadThickness, 1.0, ribbonWave);

        // 3. Flowing Pulses of Light
        // Pulses ride perfectly along the isolines without jumping tracks
        float pulseWave = sin(wavePhase * 0.3 + t * 3.0);
        float pulse = smoothstep(0.8, 1.0, pulseWave);

        // --- Lush Compositing ---
        // Core thread color
        vec3 layerColor = mix(baseCol, pulseCol, pulse * pulseInt) * ribbon;

        // Soft neon light leak spreading from the threads
        float neonGlow = smoothstep(0.5, 1.0, ribbonWave) * u_neon_glow * 0.5;
        layerColor += mix(baseCol, pulseCol, pulse) * neonGlow;

        // Add layer to final image
        finalColor += layerColor * fade * u_intensity;
    }

    // --- Calming Post-Processing ---
    // Central Bloom Anchor
    finalColor += baseCol * u_bloom * exp(-length(uv0) * 2.5);

    // Soft Vignette to prevent edge-distraction
    float vig = smoothstep(1.2, 0.2, length(uv0));
    finalColor *= vig;

    // Smooth tone mapping
    finalColor = pow(finalColor, vec3(0.9));

    fragColor = vec4(finalColor, 1.0);
}
